  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "The highest-transfer analogue, a triterpenoid saponin, reached 248.7 ng/g in rat brain, showing that some large glycosides can achieve CNS exposure; however, this is tied to its amphiphilic triterpene aglycone, which is absent in the query's cyclic oligosaccharide scaffold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C04"],
      "claim": "Anemoside B4, a lupane-type saponin, crossed the BBB after oral dosing; this positive glycoside result does not transfer to the query because the query lacks a lipophilic aglycone and is instead a highly hydroxylated cyclic sugar.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "A glucose-bearing small molecule crossed the BBB via GLUT1-mediated transport; this mechanism cannot be extrapolated to a large cyclic oligosaccharide, which is not a typical GLUT1 substrate and has a much larger polar surface area.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Fail: the query is a large, highly polar cyclic oligosaccharide (hydroxypropyl cyclodextrin-like) with no lipophilic aglycone. The positive brain penetration seen for saponin/flavonoid glycosides depends on amphiphilic aglycones or small-molecule transporter recognition and does not transfer to this scaffold, so meaningful CNS access after systemic administration is unlikely.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the query or a close cyclodextrin analogue in the retrieved evidence.",
    "All retrieved positive records are glycosides/saponins with lipophilic aglycones; none share the cyclic oligosaccharide architecture.",
    "No efflux-transporter or permeability data are available for the query scaffold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

